class Swap {
    int a, b;
    Swap(int x, int y) {
        a = x;
        b = y;
    }
    void swapValues() {
        int temp = a;
        a = b;
        b = temp;
    }
    void display() {
        System.out.println("a = " + a + ", b = " + b);
    }
    public static void main(String args[]) {
        Swap obj = new Swap(10, 20);
        obj.swapValues();
        obj.display();
    }
}
// a, b : data members holding the two values
// x, y : formal parameters of the constructor
// temp : temporary variable used for swapping

