Output: Commission in Rupees = 300.0

class Salesman {
    double sales, commission;

    Salesman() {
        sales = 0;          // initializes sales to 0
        commission = 0;     // initializes commission to 0
    }

    Salesman(double s, double c) {
        sales = s;
        commission = c;
    }

    public static void main(String args[]) {
        Salesman obj = new Salesman();        // both values are 0
        System.out.println("Initial sales = " + obj.sales + ", commission = " + obj.commission);
        Salesman obj1 = new Salesman(15000, 2);
        double comInRupees = obj1.commission / 100 * obj1.sales;
        System.out.println("Commission in Rupees = " + comInRupees);
    }
}
// sales       : sales in rupees
// commission  : commission in percent
// s, c        : formal parameters of the constructor
// comInRupees : commission earned in rupees (2/100 * 15000 = 300.0)

import java.util.*;

class FruitJuice {
    int product_code;
    String flavour;
    String pack_type;
    int pack_size;
    int product_price;

    FruitJuice() {
        product_code = 0;
        flavour = "";
        pack_type = "";
        pack_size = 0;
        product_price = 0;
    }

    void input() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter product code: ");
        product_code = sc.nextInt();
        sc.nextLine();
        System.out.print("Enter flavour: ");
        flavour = sc.nextLine();
        System.out.print("Enter pack type: ");
        pack_type = sc.nextLine();
        System.out.print("Enter pack size (ml): ");
        pack_size = sc.nextInt();
        System.out.print("Enter product price: ");
        product_price = sc.nextInt();
    }

    void discount() {
        product_price = product_price - 10;
    }

    void display() {
        System.out.println("Product code  : " + product_code);
        System.out.println("Flavour       : " + flavour);
        System.out.println("Pack type     : " + pack_type);
        System.out.println("Pack size     : " + pack_size + " ml");
        System.out.println("Product price : " + product_price);
    }

    public static void main(String args[]) {
        FruitJuice ob = new FruitJuice();
        ob.input();
        ob.discount();
        ob.display();
    }
}
// product_code  : product code number
// flavour       : flavour of the juice
// pack_type     : type of packaging
// pack_size     : package size in ml
// product_price : price of the product
// ob            : object of FruitJuice

import java.util.*;

class Employee {
    int code;
    String name;
    double basic, hra, da, PF;

    Employee() {
        code = 0;
        name = "";
        basic = 0;
        hra = 0;
        da = 0;
        PF = 0;
    }

    Employee(int c, String n, double b) {
        code = c;
        name = n;
        basic = b;
        hra = 10.0 / 100 * basic;
        da = 55.0 / 100 * basic;
        PF = 1000;
    }

    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter employee code: ");
        int cd = sc.nextInt();
        sc.nextLine();
        System.out.print("Enter name: ");
        String nm = sc.nextLine();
        System.out.print("Enter basic salary: ");
        double bs = sc.nextDouble();
        Employee emp = new Employee(cd, nm, bs);
        double netSalary = emp.basic + emp.da + emp.hra - emp.PF;
        System.out.println("EMPLOYEE PAYSLIP");
        System.out.println("CODE       : " + emp.code);
        System.out.println("NAME       : " + emp.name);
        System.out.println("NET SALARY : " + netSalary);
    }
}
// code, name, basic : employee code, name and basic salary
// hra, da, PF       : allowances and provident fund
// cd, nm, bs        : values input in main (actual parameters)
// netSalary         : basic + da + hra - PF
(Note: the source answer placed main outside the class; it must be inside class Employee.)

import java.util.*;

class Color {
    String colTop, colBottom;

    Color() {
        colTop = "Pink";
        colBottom = "Black";
    }

    Color(String t, String b) {
        colTop = t;
        colBottom = b;
