        String s1 = sc.nextLine();
        System.out.print("Enter bottom color: ");
        String s2 = sc.nextLine();
        Color dress2 = new Color(s1, s2);
        System.out.println("Assigned colors: top = " + dress2.colTop + ", bottom = " + dress2.colBottom);
    }
}
// colTop, colBottom : colors of the top and bottom of the dress
// t, b              : formal parameters of the parameterized constructor
// s1, s2            : colors entered by the user (actual parameters)
// dress1, dress2    : objects created with the default and parameterized constructors

