import java.util.*;

class ComputeNumber {
    int number;
    int d, s;
    double h;

    ComputeNumber(int a) {
        number = a;
        d = 2 * number;          // double
        s = number * number;     // square
        h = number / 2.0;        // half (2.0 avoids integer division)
    }

    void display() {
        System.out.println("Double of " + number + " = " + d);
        System.out.println("Square of " + number + " = " + s);
        System.out.println("Half of " + number + " = " + h);
    }

    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter an integer: ");
        int n = sc.nextInt();
        ComputeNumber ob = new ComputeNumber(n);
        ob.display();
    }
}
// number : the integer passed to the constructor
// d, s   : double and square of number
// h      : half of number (double)
// a      : formal parameter; n : actual parameter; ob : object

