import java.util.*;

class NumberOperations {
    int number;

    NumberOperations(int num) {
        number = num;
    }

    double calculateCube() {
        return Math.pow(number, 3);
    }

    double calculateSquareRoot() {
        return Math.sqrt(number);
    }

    double calculateReciprocal() {
        return 1.0 / number;
    }

    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter an integer number: ");
        int num = sc.nextInt();
        NumberOperations obj = new NumberOperations(num);
        System.out.println("Number: " + num);
        System.out.println("Cube: " + obj.calculateCube());
        System.out.println("Square Root: " + obj.calculateSquareRoot());
        System.out.println("Reciprocal: " + obj.calculateReciprocal());
    }
}
// number : data member set by the constructor
// num    : number entered by the user
// obj    : object of NumberOperations

import java.util.*;

class movieMagic {
    int year;
    String title;
    float rating;

    movieMagic() {
        year = 0;
        title = "";
        rating = 0.0f;
    }

    void accept() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter year of release: ");
        year = sc.nextInt();
        sc.nextLine();
        System.out.print("Enter title: ");
        title = sc.nextLine();
        System.out.print("Enter rating (0.0 to 5.0): ");
        rating = sc.nextFloat();
    }

    void display() {
        System.out.println("Title: " + title);
        if (rating <= 2.0)
            System.out.println("Flop");
        else if (rating <= 3.4)
            System.out.println("Semi-hit");
        else if (rating <= 4.5)
            System.out.println("Hit");
        else
            System.out.println("Super Hit");
    }

    public static void main(String args[]) {
        movieMagic mov = new movieMagic();
        mov.accept();
        mov.display();
    }
}
// year   : year of release
// title  : title of the movie
// rating : popularity rating, 0.0 to 5.0
// mov    : object of movieMagic
