import java.util.*;

class Days {
    public int day1, day2;

    Days(int d1, int d2) {
        day1 = d1;
        day2 = d2;
    }
}

class Difference {
    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter first day: ");
        int dd1 = sc.nextInt();
        System.out.print("Enter second day: ");
        int dd2 = sc.nextInt();
        Days obj = new Days(dd1, dd2);
        int diff = Math.abs(obj.day2 - obj.day1);
        System.out.println("Difference in number of days = " + diff);
    }
}
// day1, day2 : public data members of Days
// d1, d2     : formal parameters of the constructor
// dd1, dd2   : actual parameters entered by the user
// diff       : difference between the two days
