class Box {
    double length, width, height;

    Box() {
        length = 0;
        width = 0;
        height = 0;
    }

    Box(double l, double w, double h) {
        length = l;
        width = w;
        height = h;
    }

    double volume() {
        return length * width * height;
    }

    public static void main(String args[]) {
        Box obj = new Box(3.89, 2.1, 1.5);
        System.out.println("Volume of the box = " + obj.volume() + " cubic cm");
    }
}
// length, width, height : dimensions of the box
// l, w, h               : formal parameters
// obj                   : Box object with the given dimensions

