class TriangleSide {
    double longestSide, base;

    TriangleSide(double l, double b) {
        longestSide = l;
        base = b;
    }

    public static void main(String args[]) {
        TriangleSide t = new TriangleSide(6, 4);
        double s3 = Math.sqrt(t.longestSide * t.longestSide - t.base * t.base);
        System.out.println("The third side = " + s3);
    }
}
// longestSide, base : hypotenuse and base of the right-angled triangle
// l, b              : formal parameters of the constructor
// s3                : third side = sqrt(hypotenuse^2 - base^2)

Output: The perimeter of the isosceles triangle is: 16.0 cm

class IsoscelesTriangle {
    double side1, side2, base;

    IsoscelesTriangle(double s1, double s2, double b) {
        side1 = s1;
        side2 = s2;
        base = b;
    }

    double calculatePerimeter() {
        return side1 + side2 + base;
    }

    public static void main(String args[]) {
        IsoscelesTriangle triangle = new IsoscelesTriangle(5.0, 5.0, 6.0);
        double perimeter = triangle.calculatePerimeter();
        System.out.println("The perimeter of the isosceles triangle is: " + perimeter + " cm");
    }
}
// side1, side2 : equal sides (5 cm each); base : base (6 cm)
// s1, s2, b    : formal parameters of the constructor
// perimeter    : side1 + side2 + base = 16.0

