import java.util.*;

class Box {
    double length, width, height, volume, surfaceArea;

    Box(double l, double w, double h) {
        length = l;
        width = w;
        height = h;
    }

    void calculate() {
        volume = length * width * height;
        surfaceArea = 2 * (length * width + width * height + height * length);
    }

    void display() {
        System.out.println("Volume: " + volume);
        System.out.println("Surface Area: " + surfaceArea);
    }

    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter length, width and height: ");
        double l = sc.nextDouble(), w = sc.nextDouble(), h = sc.nextDouble();
        Box ob = new Box(l, w, h);
        ob.calculate();
        ob.display();
    }
}
// length, width, height : dimensions of the box
// volume, surfaceArea   : computed results
// l, w, h               : values input in main; ob : object
